interface Request { type: string; payload: any }
interface Handler { setNext(h: Handler): Handler; handle(req: Request): string | null }
class BaseHandler implements Handler {
  protected next?: Handler
  setNext(h: Handler) { this.next = h; return h }
  handle(req: Request) { return this.next ? this.next.handle(req) : null }
}
class AHandler extends BaseHandler { handle(req: Request) { if (req.type === 'A') return 'A done'; return super.handle(req) } }
const chain = new AHandler()
chain.setNext(new BaseHandler())
chain.handle({ type: 'A', payload: {} })

interface Request { user?: string; amount: number }
class AuthHandler { handle(req: Request) { if (!req.user) { console.log('unauthenticated'); return true } return false } }
class ValidationHandler { handle(req: Request) { if (req.amount <= 0) { console.log('invalid amount'); return true } return false } }
const auth = new AuthHandler()
const validation = new ValidationHandler()
function process(req: Request) {
  if (auth.handle(req)) return
  if (validation.handle(req)) return
  console.log('process payment')
}

// Version A: handlers forward to next
interface Req { type: string }
class HandlerA {
  next?: HandlerA
  setNext(n: HandlerA) { this.next = n }
  handle(r: Req) { if (r.type === 'A') return 'A'; return this.next?.handle(r) }
}
// compose
const a = new HandlerA(); const b = new HandlerA(); a.setNext(b);

// Version B: central dispatcher decides order
function process(r: Req) {
  if (a.handle(r)) return
  if (b.handle(r)) return
  return null
}
